    [ApplicantID] NVARCHAR(50) NULL,
    [Fullname] NVARCHAR(50) NULL,
    [PositionTitle] NVARCHAR(50) NULL,
    [CompanyName] NVARCHAR(50) NULL,
    [Relationship] NVARCHAR(50) NULL,
    [Email] NVARCHAR(50) NULL,
    [PhoneContact] NVARCHAR(50) NULL,
    [ReferenceType] NVARCHAR(50) NULL,
    [Notes] NVARCHAR(50) NULL,
    [VerifiedBy] NVARCHAR(50) NULL,
    [VerifiedAt] DATETIME NULL,
    [AddedAt] DATETIME NULL,
    [UpdatedAt] DATETIME NULL,
    CONSTRAINT [PK_References] PRIMARY KEY ([ID])
);
CREATE TABLE dbo.[Skills] (
    [ID] NVARCHAR(50) NOT NULL,
    [SkillName] NVARCHAR(50) NULL,
    [SkillCategoryID] NVARCHAR(50) NULL,
    [Status] NVARCHAR(50) NULL,
    [AddedAt] DATETIME NULL,
    [AddedBy] NVARCHAR(50) NULL,
    [UpdatedAt] DATETIME NULL,
    [UpdatedBy] NVARCHAR(50) NULL,
    CONSTRAINT [PK_Skills] PRIMARY KEY ([ID])
);
CREATE TABLE dbo.[SkillCategory] (
    [ID] NVARCHAR(50) NOT NULL,
    [CategoryName] NVARCHAR(50) NULL,
    [Deleted] BIT NULL,
    CONSTRAINT [PK_SkillCategory] PRIMARY KEY ([ID])
);
CREATE TABLE dbo.[ApplicantSkills] (
    [ID] NVARCHAR(50) NOT NULL,
    [SkillID] NVARCHAR(50) NULL,
    [ApplicantID] NVARCHAR(50) NULL,
    [AddedAt] DATETIME NULL,
    [UpdatedAt] DATETIME NULL,
    CONSTRAINT [PK_ApplicantSkills] PRIMARY KEY ([ID])
);
GO
